# Purpose: Kernel discrimination. Both kernel families are fitted to data
# generated by each of them and compared by Pareto smoothed importance sampling
# leave one out cross-validation, and the outcome is related to the index
# m_star of Corollary 1.
# Manuscript: Section 5.3, Experiment 2.6; Corollary 1.
# Inputs: an experiment configuration and the generated synthetic data.
# Outputs: a tracked summary under results/summary/.

import argparse  # Command line interface of the experiment script.
import sys  # Process exit status of the experiment script.
from pathlib import Path  # Portable filesystem paths.

import numpy as np  # Numerical arrays and random number generation.

from nmi.config import load_experiment_config  # Configuration loader with base inheritance.
from nmi.design import design_1d  # Construction of the factorial design.
from nmi.io import read_condition_data, write_csv  # Data reader and summary writer.
from nmi.likelihood import (  # Forward map and log-likelihood of the transient observations.
    forward_transient_loglik,  # Log-likelihood of the transient observations.
    make_log_posterior,  # Unnormalised log posterior built from a likelihood and a prior.
    predict_transient,  # Prediction of the transient forward map.
    transient_context,  # Context mapping of the transient forward map.
)
from nmi.linear_theory import m_star  # Index of the first nonpositive top-hat multiplier.
from nmi.mcmc_adaptive import AdaptiveMetropolis  # Adaptive random-walk Metropolis sampler.
from nmi.priors import transient_prior  # Log-uniform prior on the four free parameters.
from nmi.wolf.model_comparison import compare_models  # Leave one out cross-validation.


# Parse the command line arguments of the script.
# Arguments:
#   argv (list): command line arguments after the program name.
# Returns:
#   argparse.Namespace: the parsed arguments.
def parse_arguments(argv):
    parser = argparse.ArgumentParser(description="Kernel discrimination")  # Argument parser.
    parser.add_argument("--config", required=True, help="experiment configuration")  # Configuration.
    parser.add_argument("--output-dir", default=None, help="raw output directory")  # Destination.
    return parser.parse_args(argv)  # Parsed command line arguments of the script.


# Fit one kernel family to the data of one condition and return the draws.
# Arguments:
#   condition (dict): the condition that generated the data.
#   fitted_kernel (str): the kernel family that is fitted to those data.
#   config (dict): the configuration mapping of the run.
#   settings (dict): the discrimination block of the configuration.
# Returns:
#   tuple: the retained draws in log space and the fitting context.
def fit_kernel(condition, fitted_kernel, config, settings):
    fitted = dict(condition)  # Copy of the condition whose kernel family is replaced.
    fitted["kernel"] = fitted_kernel  # Kernel family that is fitted to the generated data.
    data = read_condition_data(config["experiment"], condition["index"])  # Generated data.
    context = transient_context(fitted, config)  # Context of the fitted forward map.
    prior = transient_prior(condition["advection"], config["design"]["priors"])  # Prior of Table 3.
    observations = {  # Data mapping used by the transient log-likelihood.
        "observations": data["observations"],  # Noisy transient observations.
        "sigma": data["sigma"],  # Standard deviation of the observation noise.
    }
    # Unnormalised log posterior of the fitted kernel family, in log space.
    log_posterior = make_log_posterior(
        lambda point: forward_transient_loglik(point, observations, context),  # Log-likelihood.
        prior,  # Log-uniform prior on the four free parameters.
    )  # Callable passed to the sampler of this fit.
    start = np.log(  # Start the chain at the true parameters of the generating condition.
        [  # Reduced parameter vector in the order used by the samplers.
            float(condition["diffusion"]),  # True diffusion rate d.
            float(condition["advection"]),  # True combined advection strength gamma.
            float(condition["memory_decay"]),  # True memory decay rate mu.
            float(condition["radius"]),  # True perceptual range R.
        ]
    )  # Starting point of the chain of this fit.
    sampler = AdaptiveMetropolis(  # Sampler of this fit.
        log_posterior,  # Unnormalised log posterior of the fitted kernel family.
        start,  # Starting point of the chain of this fit.
        0.05,  # Standard deviation of the initial diagonal proposal.
        200,  # Iteration at which the covariance adaptation begins.
        rng=np.random.default_rng(int(settings["seed"]) + condition["index"]),  # Deterministic.
    )  # Sampler in its initial state.
    result = sampler.run(int(settings["n_iterations"]))  # Chain of this fit.
    chain = result["chain"]  # States of the chain, one row per iteration.
    kept = chain[int(float(settings["burn_in_fraction"]) * chain.shape[0]) :]  # Retained draws.
    return kept, context, observations  # Draws, forward context and the observed data.


# Pointwise log-likelihood contributions of a set of posterior draws.
# Arguments:
#   draws (numpy.ndarray): retained draws in log space.
#   context (dict): the context mapping of the fitted forward map.
#   observations (dict): the observed values and the noise scale.
#   n_draws (int): number of draws retained for the cross-validation.
# Returns:
#   numpy.ndarray: contributions of shape (draws, observations).
def pointwise_contributions(draws, context, observations, n_draws):
    values = np.asarray(observations["observations"], dtype=float).ravel()  # Observed values.
    sigma = float(observations["sigma"])  # Standard deviation of the observation noise.
    stride = max(1, draws.shape[0] // int(n_draws))  # Stride that thins the chain.
    thinned = draws[::stride][: int(n_draws)]  # Draws retained for the cross-validation.
    matrix = np.full((thinned.shape[0], values.size), -np.inf)  # Storage of the contributions.
    for position, point in enumerate(thinned):  # Evaluate the forward map at each retained draw.
        prediction = predict_transient(point, context)  # Prediction at the sampling points.
        if prediction is None:  # The draw was rejected by the positivity monitor.
            continue  # Leave the row at minus infinity, which excludes the draw.
        residual = values - np.asarray(prediction, dtype=float).ravel()  # Pointwise residuals.
        constant = -0.5 * np.log(2.0 * np.pi * sigma**2)  # Normalising constant of the density.
        matrix[position] = constant - 0.5 * residual**2 / sigma**2  # Pointwise log densities.
    finite = np.all(np.isfinite(matrix), axis=1)  # Draws at which every contribution is finite.
    return matrix[finite]  # Contributions of the admissible draws only.


# Entry point of the kernel discrimination study.
# Arguments:
#   argv (list): command line arguments after the program name.
# Returns:
#   int: zero on success.
def main(argv):
    arguments = parse_arguments(argv)  # Parsed command line arguments of the script.
    config = load_experiment_config(arguments.config)  # Merged and validated configuration.
    settings = config["discrimination"]  # Settings of the kernel discrimination study.
    design = design_1d(config)  # Factorial design of the one-dimensional experiments.
    length = float(config["design"]["domain_length"])  # Length L of the periodic domain.
    radii = [float(value) for value in settings["radii"]]  # Perceptual ranges of the study.
    noises = [float(value) for value in settings["noise_levels"]]  # Noise levels of the study.
    records = []  # Accumulator for the rows of the discrimination table.
    for condition in design["transient"]:  # Select the generating conditions of the study.
        # Whether the perceptual range of this condition enters the study.
        matches_radius = any(abs(condition["radius"] - value) < 1.0e-12 for value in radii)
        # Whether the noise level of this condition enters the study.
        matches_noise = any(abs(condition["noise_level"] - value) < 1.0e-12 for value in noises)
        # Only the configured combinations take part in the discrimination study.
        if not (matches_radius and matches_noise and condition["sampling"] == settings["sampling"]):
            continue  # Skip conditions that are not part of the discrimination study.
        contributions = {}  # Pointwise contributions of each fitted kernel family.
        for fitted_kernel in ("tophat", "gaussian"):  # Fit both kernel families to these data.
            # Fit the current kernel family to the data of this condition.
            draws, context, observations = fit_kernel(condition, fitted_kernel, config, settings)
            # Pointwise contributions of the retained draws of this fit.
            contributions[fitted_kernel] = pointwise_contributions(
                draws,  # Retained draws of this fit.
                context,  # Context of the fitted forward map.
                observations,  # Observed values and the noise scale.
                int(settings["n_draws"]),  # Number of draws used for the cross-validation.
            )  # Contributions used by the leave one out comparison.
        comparison = compare_models(contributions)  # Leave one out comparison of the two fits.
        preferred = comparison[0]["model"]  # Kernel family preferred by the comparison.
        # Index m_star of Corollary 1, reported for the top-hat conditions.
        index = m_star(condition["radius"], length) if condition["kernel"] == "tophat" else ""
        for entry in comparison:  # Record one row per fitted kernel family.
            records.append(  # One row of the discrimination table.
                {  # Outcome of the comparison for this fitted kernel family.
                    "condition_index": condition["index"],  # Index of the generating condition.
                    "identifier": condition["identifier"],  # Label of the generating condition.
                    "generating_kernel": condition["kernel"],  # Kernel that generated the data.
                    "fitted_kernel": entry["model"],  # Kernel family that was fitted.
                    "radius": condition["radius"],  # Perceptual range R of the condition.
                    "noise_level": condition["noise_level"],  # Relative noise level eta.
                    "m_star": index,  # Index m_star of Corollary 1, for the top-hat kernel.
                    "elpd": entry["elpd"],  # Expected log pointwise predictive density.
                    "elpd_difference": entry["elpd_difference"],  # Difference from the best fit.
                    "difference_se": entry["difference_se"],  # Standard error of the difference.
                    "max_pareto_k": entry["max_pareto_k"],  # Largest Pareto shape value.
                    "preferred": entry["model"] == preferred,  # Whether this fit is preferred.
                    "correct": preferred == condition["kernel"],  # Whether the truth is recovered.
                }
            )  # Row appended to the discrimination table.
        print(f"discrimination {condition['identifier']}: preferred {preferred}")  # Report.
    if not records:  # No condition of the design matched the settings of the study.
        print("no condition matched the kernel discrimination settings")  # Report the mismatch.
        return 0  # Signal success, since an empty selection is a configuration choice.
    summary = Path("results/summary") / f"{config['experiment']}_kernel_discrimination.csv"  # Path.
    write_csv(summary, records, list(records[0].keys()))  # Write the tracked summary table.
    print(f"wrote {summary} with {len(records)} row(s)")  # Report the location of the summary.
    return 0  # Signal success to the caller.


if __name__ == "__main__":  # Allow the module to be used as a command line script.
    sys.exit(main(sys.argv[1:]))  # Run the experiment and propagate the exit status.
